import calendar
from datetime import date, timedelta


def recur(start: str, rule: str, count: int) -> list[str]:
    weekdays = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}
    start_date = date.fromisoformat(start)
    parts = rule.split(" ")
    freq = parts[0]
    k = int(parts[1])
    result: list[str] = []

    if freq == "DAILY":
        for i in range(count):
            result.append((start_date + timedelta(days=i * k)).isoformat())
        return result

    if freq == "WEEKLY":
        target_wds = sorted(weekdays[d] for d in parts[2].split(","))
        week0_monday = start_date - timedelta(days=start_date.weekday())
        week = 0
        while len(result) < count:
            monday = week0_monday + timedelta(days=week * 7)
            for wd in target_wds:
                candidate = monday + timedelta(days=wd)
                if candidate >= start_date:
                    result.append(candidate.isoformat())
                    if len(result) == count:
                        return result
            week += k
        return result

    if freq == "MONTHLY":
        m0 = start_date.year * 12 + (start_date.month - 1)
        step = 0
        if len(parts) == 3:
            target_day = int(parts[2])
            while len(result) < count:
                year, month0 = divmod(m0 + step * k, 12)
                month = month0 + 1
                days_in_month = calendar.monthrange(year, month)[1]
                day = days_in_month if target_day == -1 else target_day
                if 1 <= day <= days_in_month:
                    candidate = date(year, month, day)
                    if candidate >= start_date:
                        result.append(candidate.isoformat())
                step += 1
        else:
            n = int(parts[2])
            target_wd = weekdays[parts[3]]
            while len(result) < count:
                year, month0 = divmod(m0 + step * k, 12)
                month = month0 + 1
                first_wd, days_in_month = calendar.monthrange(year, month)
                if n == -1:
                    last_wd = (first_wd + days_in_month - 1) % 7
                    day = days_in_month - (last_wd - target_wd) % 7
                else:
                    first_match = 1 + (target_wd - first_wd) % 7
                    day = first_match + (n - 1) * 7
                if 1 <= day <= days_in_month:
                    candidate = date(year, month, day)
                    if candidate >= start_date:
                        result.append(candidate.isoformat())
                step += 1
        return result

    if freq == "YEARLY":
        month_str, day_str = parts[2].split("-")
        month = int(month_str)
        day = int(day_str)
        year = start_date.year
        while len(result) < count:
            try:
                candidate = date(year, month, day)
            except ValueError:
                year += k
                continue
            if candidate >= start_date:
                result.append(candidate.isoformat())
            year += k
        return result

    raise ValueError(f"Unsupported rule: {rule}")
